SELECT DATE_TRUNC('QUARTER', signup_date) AS quarter_start, city, COUNT(DISTINCT city) AS distinct_cities, BIT_OR(age) AS age_bit_or, CORR(credit_limit, age) AS corr_credit_limit_age, APPROX_PERCENTILE(credit_limit, 0.5) AS credit_limit_p50, PERCENTILE_APPROX(age, 0.5) AS age_p50, ROUND(AVG(credit_limit), 2) AS avg_credit_limit, PERCENT_RANK() OVER (PARTITION BY DATE_TRUNC('QUARTER', signup_date) ORDER BY PERCENTILE_APPROX(age, 0.5) DESC) AS age_p50_percent_rank FROM customers GROUP BY DATE_TRUNC('QUARTER', signup_date), city HAVING CORR(credit_limit, age) < 1000000;
